command:
$ErrorActionPreference = "Stop"
git fetch origin main --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch main failed" }
if ((git rev-parse origin/main).Trim() -ne "591ecbad86a133812fa27521ca771aaba15e2ffe") { throw "main moved" }

$before="C:\dev\flyExplorer\logs\filter-preset-before.png"
$after="C:\dev\flyExplorer\logs\filter-preset-after.png"
if (-not (Test-Path $before) -or -not (Test-Path $after)) { throw "visual evidence missing" }

$review=Join-Path $env:RUNNER_TEMP "fly-filter-preset-review"
if (Test-Path $review) { Remove-Item -Recurse -Force $review }
git -C $env:GITHUB_WORKSPACE fetch origin work/filter-presets --no-tags
if ($LASTEXITCODE -ne 0) { throw "fetch work branch failed" }
git -C $env:GITHUB_WORKSPACE worktree add --detach $review origin/work/filter-presets
if ($LASTEXITCODE -ne 0) { throw "review worktree failed" }
New-Item -ItemType Directory -Force -Path (Join-Path $review "review") | Out-Null
Copy-Item $before (Join-Path $review "review\filter-preset-before.png")
Copy-Item $after (Join-Path $review "review\filter-preset-after.png")
git -C $review add -f review/filter-preset-before.png review/filter-preset-after.png
git -C $review -c user.name="flyExplorer Review" -c user.email="review@flyexplorer.invalid" commit -m "review: temporary filter preset visual evidence"
if ($LASTEXITCODE -ne 0) { throw "review commit failed" }
git -C $review push origin HEAD:refs/heads/work/filter-presets
if ($LASTEXITCODE -ne 0) { throw "review push failed" }
git -C $env:GITHUB_WORKSPACE worktree remove --force $review
Write-Host "FILTER_PRESET_VISUAL_REVIEW_PUBLISHED"
